presets.customCss:
body::before {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') no-repeat center center / cover !important;
  z-index: -999 !important;
  pointer-events: none;
}

.xs-panel {
  --xs-bg: transparent; 
  --xs-tile-bg: #FFFFFF; 
  --xs-text: #4A1525;
  --xs-muted: #A8808E;
  --xs-accent: #FF69B4;
  --xs-border: #FFB6C1;
  --xs-cap: #4A1525;
  --xs-action-bg: rgba(255, 255, 255, 0.8);
  --xs-done-bg: rgba(255, 182, 193, 0.8);

  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;

  width: 100% !important;
  max-width: 100% !important;
  margin: 0 auto !important; 
  padding: 20px 16px !important; 
  border-radius: 0px !important;
}

.xs-frame {
  width: 100% !important;
  max-width: 100% !important;
}

.xs-tile {
  background: #FFFFFF !important;
  border: 1px solid var(--xs-border) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}

.xs-tile-deep {
  background: #FFFFFF !important;
  opacity: 1 !important;
}

.xs-tile-deep .xs-tile-v,
.xs-tile-deep .xs-tile-k,
.xs-tile .xs-tile-v,
.xs-tile .xs-tile-k {
  color: #4A1525 !important;
}

.xs-action {
  background: #FFFFFF !important;
  border: 1px solid var(--xs-border) !important;
  color: #4A1525 !important;
}

.xs-history {
  background: rgba(255, 255, 255, 0.6) !important;
  border: 1px solid rgba(255, 182, 193, 0.4) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}

.xs-history-item {
  background: transparent !important;
  border-bottom: 1px solid rgba(255, 182, 193, 0.2) !important;
}
